const config = {
  type: Phaser.AUTO,
  width: 640,
  height: 640,
  backgroundColor: '#2d2d2d',
  scene: { preload, create, update }
};

const gridSize = 32;
let snake, food, cursors, direction, newDirection, score = 0, scoreText;
let moveTime = 0;

const game = new Phaser.Game(config);

function preload() {
  const graphics = this.make.graphics({ x: 0, y: 0, add: false });

  // Snake segment (green)
  graphics.fillStyle(0x00ff00, 1);
  graphics.fillRect(0, 0, gridSize - 2, gridSize - 2);
  graphics.generateTexture('snake', gridSize, gridSize);
  graphics.clear();

  // Food (red)
  graphics.fillStyle(0xff0000, 1);
  graphics.fillCircle(gridSize / 2, gridSize / 2, gridSize / 2 - 2);
  graphics.generateTexture('food', gridSize, gridSize);
}

function create() {
  snake = [];
  direction = { x: 1, y: 0 };
  newDirection = { x: 1, y: 0 };

  // Create initial snake
  for (let i = 0; i < 3; i++) {
    snake.push(this.add.sprite(160 - i * gridSize, 160, 'snake'));
  }

  // Create food
  food = this.add.sprite(0, 0, 'food');
  repositionFood();

  // Input
  cursors = this.input.keyboard.createCursorKeys();

  // Score
  scoreText = this.add.text(16, 16, 'Score: 0', {
    fontSize: '24px',
    fill: '#fff'
  });
}

function update(time) {
  // Handle input
  if (cursors.left.isDown && direction.x !== 1) {
    newDirection = { x: -1, y: 0 };
  } else if (cursors.right.isDown && direction.x !== -1) {
    newDirection = { x: 1, y: 0 };
  } else if (cursors.up.isDown && direction.y !== 1) {
    newDirection = { x: 0, y: -1 };
  } else if (cursors.down.isDown && direction.y !== -1) {
    newDirection = { x: 0, y: 1 };
  }

  // Move snake every 150ms
  if (time >= moveTime) {
    moveTime = time + 150;
    direction = newDirection;

    const head = snake[0];
    const newX = head.x + direction.x * gridSize;
    const newY = head.y + direction.y * gridSize;

    // Check collisions
    if (newX < 0 || newX >= 640 || newY < 0 || newY >= 640) {
      gameOver();
      return;
    }

    for (let segment of snake) {
      if (segment.x === newX && segment.y === newY) {
        gameOver();
        return;
      }
    }

    // Add new head
    const newHead = this.add.sprite(newX, newY, 'snake');
    snake.unshift(newHead);

    // Check if eating food
    if (newX === food.x && newY === food.y) {
      score += 10;
      scoreText.setText('Score: ' + score);
      repositionFood();
    } else {
      // Remove tail
      const tail = snake.pop();
      tail.destroy();
    }
  }
}

function repositionFood() {
  const x = Phaser.Math.Between(0, 19) * gridSize;
  const y = Phaser.Math.Between(0, 19) * gridSize;

  // Make sure food doesn't spawn on snake
  for (let segment of snake) {
    if (segment.x === x && segment.y === y) {
      repositionFood();
      return;
    }
  }

  food.setPosition(x, y);
}

function gameOver() {
  scoreText.setText('Game Over! Score: ' + score + ' - Reload to restart');
  this.scene.pause();
}
